// Compatibility renderer for browsers without WebGL. Projects the actual Babylon
// triangle meshes and skinned vertices; the same scene, skeletons and Havok world run.
export function createSoftwareRenderer(canvas,B,scene,engine){const c=canvas.getContext('2d',{alpha:false}),cache=new WeakMap(),v=new B.Vector3(),w=new B.Vector3(),p=new B.Vector3();let last=0,frames=0,fps=0,triangles=0;
 function data(mesh){let d=cache.get(mesh.geometry);if(!d){const positions=mesh.getVerticesData(B.VertexBuffer.PositionKind);if(!positions)return null;let indices=mesh.getIndices();if(!indices?.length)indices=Array.from({length:positions.length/3},(_,i)=>i);d={positions,indices,joints:mesh.getVerticesData(B.VertexBuffer.MatricesIndicesKind),weights:mesh.getVerticesData(B.VertexBuffer.MatricesWeightsKind),uv:mesh.getVerticesData(B.VertexBuffer.UVKind)};cache.set(mesh.geometry,d);}return d;}
 function render(){const rect=canvas.getBoundingClientRect(),scale=Math.min(1,900/rect.width),width=Math.round(rect.width*scale),height=Math.round(rect.height*scale);if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;engine.setSize(width,height);}const bg=scene.clearColor;c.fillStyle=`rgb(${bg.r*255},${bg.g*255},${bg.b*255})`;c.fillRect(0,0,width,height);const vp=scene.getTransformMatrix(),faces=[],active=scene.getActiveMeshes();for(const mesh of Array.from({length:active.length},(_,i)=>active.data[i])){if(!mesh.isEnabled()||!mesh.isVisible||mesh.visibility<.03||!mesh.geometry||mesh.metadata?.softwareSkip)continue;const d=data(mesh);if(!d)continue;const world=mesh.computeWorldMatrix(),bones=mesh.skeleton&&d.joints?mesh.skeleton.getTransformMatrices(mesh):null,projected=[],worldPositions=[];for(let i=0;i<d.positions.length;i+=3){v.set(d.positions[i],d.positions[i+1],d.positions[i+2]);if(bones){const at=i/3*4;let x=0,y=0,z=0;for(let k=0;k<4;k++){const weight=d.weights[at+k];if(!weight)continue;const j=d.joints[at+k]*16;x+=(v.x*bones[j]+v.y*bones[j+4]+v.z*bones[j+8]+bones[j+12])*weight;y+=(v.x*bones[j+1]+v.y*bones[j+5]+v.z*bones[j+9]+bones[j+13])*weight;z+=(v.x*bones[j+2]+v.y*bones[j+6]+v.z*bones[j+10]+bones[j+14])*weight;}v.set(x,y,z);}B.Vector3.TransformCoordinatesToRef(v,world,w);worldPositions.push([w.x,w.y,w.z]);B.Vector3.TransformCoordinatesToRef(w,vp,p);projected.push([(p.x*.5+.5)*width,(.5-p.y*.5)*height,p.z]);}
 const texture=mesh.metadata?.softwareTexture;const base=mesh.material?.albedoColor||mesh.material?.diffuseColor||new B.Color3(.6,.65,.7),alpha=(mesh.material?.alpha??1)*mesh.visibility;for(let i=0;i<d.indices.length;i+=3){const ids=[d.indices[i],d.indices[i+1],d.indices[i+2]],a=projected[ids[0]],b=projected[ids[1]],cc=projected[ids[2]];if(!a||!b||!cc||a[2]<0||b[2]<0||cc[2]<0||a[2]>1.01||b[2]>1.01||cc[2]>1.01)continue;if([a,b,cc].every(v=>v[0]<0)||[a,b,cc].every(v=>v[0]>width)||[a,b,cc].every(v=>v[1]<0)||[a,b,cc].every(v=>v[1]>height))continue;const A=worldPositions[ids[0]],D=worldPositions[ids[1]],E=worldPositions[ids[2]],ux=D[0]-A[0],uy=D[1]-A[1],uz=D[2]-A[2],vx=E[0]-A[0],vy=E[1]-A[1],vz=E[2]-A[2],nx=uy*vz-uz*vy,ny=uz*vx-ux*vz,nz=ux*vy-uy*vx,n=Math.hypot(nx,ny,nz)||1,shade=.62+.38*Math.abs((nx*.35+ny*.85+nz*.4)/n);faces.push({a,b,c:cc,layer:mesh.metadata?.softwareLayer||0,z:(a[2]+b[2]+cc[2])/3,texture:texture&&d.uv?{image:texture.image,alpha,uv:ids.map(i=>[d.uv[i*2]*(texture.uScale||1)+(texture.uOffset||0),texture.flipY?1-d.uv[i*2+1]:d.uv[i*2+1]])}:null,shade,color:`rgba(${Math.round(base.r*255*shade)},${Math.round(base.g*255*shade)},${Math.round(base.b*255*shade)},${alpha})`});}}
 faces.sort((a,b)=>a.layer-b.layer||b.z-a.z);for(const f of faces){if(f.texture&&drawTexturedTriangle(c,f,f.texture)){continue;}c.fillStyle=f.color;c.beginPath();c.moveTo(f.a[0],f.a[1]);c.lineTo(f.b[0],f.b[1]);c.lineTo(f.c[0],f.c[1]);c.closePath();c.fill();}triangles=faces.length;frames++;const now=performance.now();if(now-last>1000){fps=Math.round(frames*1000/(now-last));frames=0;last=now;}}
 return{render,get fps(){return fps;},get triangles(){return triangles;}};
}

/** Affine triangle sampling for compatibility only; does not claim GPU PBR/depth. */
export function drawTexturedTriangle(c,face,{image,uv,alpha=1}){if(!image?.width||!image?.height||!c.drawImage)return false;const p=[face.a,face.b,face.c],t=uv.map(v=>[v[0]*image.width,v[1]*image.height]),u1=t[1][0]-t[0][0],v1=t[1][1]-t[0][1],u2=t[2][0]-t[0][0],v2=t[2][1]-t[0][1],det=u1*v2-u2*v1;if(Math.abs(det)<1e-8)return false;const x1=p[1][0]-p[0][0],y1=p[1][1]-p[0][1],x2=p[2][0]-p[0][0],y2=p[2][1]-p[0][1],a=(x1*v2-x2*v1)/det,b=(y1*v2-y2*v1)/det,cc=(u1*x2-u2*x1)/det,d=(u1*y2-u2*y1)/det;c.save();c.globalAlpha=alpha;const sign=Math.sign((p[1][0]-p[0][0])*(p[2][1]-p[0][1])-(p[1][1]-p[0][1])*(p[2][0]-p[0][0]))||1,edge=p.map((v,i)=>{const prev=p[(i+2)%3],next=p[(i+1)%3],a=[v[0]-prev[0],v[1]-prev[1]],b=[next[0]-v[0],next[1]-v[1]],al=Math.hypot(...a)||1,bl=Math.hypot(...b)||1,n1=[sign*a[1]/al,-sign*a[0]/al],n2=[sign*b[1]/bl,-sign*b[0]/bl],k=.6/Math.max(.05,1+n1[0]*n2[0]+n1[1]*n2[1]);return[v[0]+(n1[0]+n2[0])*k,v[1]+(n1[1]+n2[1])*k];});c.beginPath();c.moveTo(edge[0][0],edge[0][1]);c.lineTo(edge[1][0],edge[1][1]);c.lineTo(edge[2][0],edge[2][1]);c.closePath();c.clip();c.transform(a,b,cc,d,p[0][0]-a*t[0][0]-cc*t[0][1],p[0][1]-b*t[0][0]-d*t[0][1]);const pattern=c.createPattern?.(image,'repeat');if(pattern){c.fillStyle=pattern;const us=t.map(v=>v[0]),vs=t.map(v=>v[1]);c.fillRect(Math.min(...us)-1,Math.min(...vs)-1,Math.max(...us)-Math.min(...us)+2,Math.max(...vs)-Math.min(...vs)+2);}else c.drawImage(image,0,0);c.restore();return true;}
